local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
  fields = { "details" },
})
classes.BigQueryServiceAccountNotReady = errors.define({
  tag = "BigQueryServiceAccountNotReady",
  categories = { "BadRequestError" },
  matchers = {
    { status = 400, message = { includes = "argument=BigQueryConfig::service_account_email" } },
  },
  fields = { "details" },
})
classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
  fields = { "details" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "details" },
})
classes.IamMemberNotFound = errors.define({
  tag = "IamMemberNotFound",
  categories = { "BadRequestError" },
  matchers = {
    { status = 400, message = { matches = "^Service account .+ does not exist\\.?$" } },
  },
  fields = { "details" },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
  fields = { "details" },
})

